mapper.select:
SELECT id, tenant_id AS tenantId, actor_username AS actorUsername, actor_user_id AS actorUserId, action, entity_type AS entityType, entity_id AS entityId, detail, status, request_id AS requestId, client_ip AS clientIp, user_agent AS userAgent, duration_ms AS durationMs, method, path, http_status AS httpStatus, error_code AS errorCode, error_message AS errorMessage, auth_tenant_id AS authTenantId, auth_tenant_code AS authTenantCode, is_cross_tenant AS crossTenant, created_at AS createdAt FROM audit_log
AND tenant_id = #{query.tenantId}
AND actor_username = #{query.actorUsername}
AND action = #{query.action}
AND entity_type = #{query.entityType}
AND status = #{query.status}
AND created_at >= #{query.startTime}
AND created_at <= #{query.endTime}
ORDER BY created_at DESC, id DESC LIMIT #{query.limit}
